          table.tableName,
          await rowsForWorkspace(
            source,
            table.tableName,
            context.namespace,
            table.namespaceColumn,
          ),
        );
        const columns = await writableTableColumns(target, table.tableName);
        columnsByTable.set(table.tableName, columns);
