+): Promise<void> {
+  for (const column of columns) {
+    if (!column.sequence_name || !column.is_globally_unique) continue;
+    for (const row of rows) {
+      await client.query(
+        `WITH source_row AS (
+           SELECT *
+             FROM jsonb_populate_record(NULL::${identifier(table)}, $1::jsonb)
